  d = opSmoothUnion(d, mod_cap2(q, bodyA, bodyB, 2.2), 1.4);
  d = opSmoothUnion(d, length(q - headP) - 1.9, 1.0);
  d = min(d, mod_cap2(q, headP, headP + rotate(vec2f(3.0, -3.0 + sin(ph * 12.566)), hd), 0.35));
  d = min(d, mod_cap2(q, headP, headP + rotate(vec2f(3.5, 1.5 + cos(ph * 12.566)), hd), 0.35));
  let mnd = sin(ph * 18.85) * 0.4;
  d = min(d, mod_cap2(q, headP + rotate(vec2f(1.5, -0.8), hd), headP + rotate(vec2f(3.2, -1.4 + mnd), hd), 0.4));
  d = min(d, mod_cap2(q, headP + rotate(vec2f(1.5, 0.6), hd), headP + rotate(vec2f(3.2, 1.2 - mnd), hd), 0.4));
  for (var i = 0; i < 6; i++) {
    let xi = f32(i % 3);
    let side = f32(i / 3) * 2.0 - 1.0;
    let tri = f32((i + i / 3) % 2);
    let baseL = vec2f(-6.0 + xi * 6.0, side * 1.5);
    let g = mod_gait(ph + tri * 0.5 + xi * 0.06, 0.55, 3.0, 2.0);
    let fx = baseL.x + g.x;
    let footL = vec2f(fx, side * 8.5 + g.y * side);
    let kneeL = vec2f((baseL.x + fx) * 0.5, side * 5.0 + baseL.y);
    let base = rotate(baseL, hd);
    let knee = rotate(kneeL, hd);
    let foot = rotate(footL, hd);
    d = min(d, mod_cap2(q, base, knee, 0.55));
    d = min(d, mod_cap2(q, knee, foot, 0.45));
  }
  return d;
}
fn mar6_crawler_sd3(p: vec3f, hd: f32, ph: f32) -> f32 {
  let bob = sin(ph * 18.85) * 0.4;
  let bodyA = rotate(vec2f(-5.0, bob), hd);
  let bodyB = rotate(vec2f(5.0, -bob), hd);
  let headP = rotate(vec2f(9.5, -bob - 1.0), hd);
  var d = mod_sph3(p, bodyA, 3.2);
  d = opSmoothUnion(d, mod_sph3(p, bodyB, 2.8), 1.6);
  d = opSmoothUnion(d, mod_cap3(p, bodyA, bodyB, 2.2), 1.4);
  d = opSmoothUnion(d, mod_sph3(p, headP, 1.9), 1.0);
  d = min(d, mod_cap3(p, headP, headP + rotate(vec2f(3.0, -3.0 + sin(ph * 12.566)), hd), 0.35));
  d = min(d, mod_cap3(p, headP, headP + rotate(vec2f(3.5, 1.5 + cos(ph * 12.566)), hd), 0.35));
  let mnd = sin(ph * 18.85) * 0.4;
  d = min(d, mod_cap3(p, headP + rotate(vec2f(1.5, -0.8), hd), headP + rotate(vec2f(3.2, -1.4 + mnd), hd), 0.4));
  d = min(d, mod_cap3(p, headP + rotate(vec2f(1.5, 0.6), hd), headP + rotate(vec2f(3.2, 1.2 - mnd), hd), 0.4));
  for (var i = 0; i < 6; i++) {
    let xi = f32(i % 3);
    let side = f32(i / 3) * 2.0 - 1.0;
    let tri = f32((i + i / 3) % 2);
    let baseL = vec2f(-6.0 + xi * 6.0, side * 1.5);
    let g = mod_gait(ph + tri * 0.5 + xi * 0.06, 0.55, 3.0, 2.0);
    let fx = baseL.x + g.x;
    let footL = vec2f(fx, side * 8.5 + g.y * side);
    let kneeL = vec2f((baseL.x + fx) * 0.5, side * 5.0 + baseL.y);
    let base = rotate(baseL, hd);
    let knee = rotate(kneeL, hd);
    let foot = rotate(footL, hd);
    d = min(d, mod_cap3(p, base, knee, 0.55));
    d = min(d, mod_cap3(p, knee, foot, 0.45));
  }
  return d;
}
fn visual_mar6_crawler(uv: vec2f, sdf: f32, col: vec4f, time: f32, p: vec4f, behind: vec4f) -> vec4f {
  let c = uv * 22.0;
  let hd = p.x; let ph = p.y;
  let d2 = mar6_crawler_sd(c, hd, ph);
  if (d2 > 3.0) {
    let ds = mar6_crawler_sd(c - vec2f(3.5, 4.5), hd, ph);
    let sh0 = smoothstep(2.2, -1.2, ds) * 0.42;
    return vec4f(vec3f(0.0), sh0);
  }
  // orthographic raymarch: camera at z = -9 looking +z
  var t = 0.0;
  var pos = vec3f(c, -9.0);
  var found = false;
  for (var i = 0; i < 40; i++) {
    pos = vec3f(c, -9.0 + t);
    let dd = mar6_crawler_sd3(pos, hd, ph);
    if (dd < 0.05) { found = true; break; }
    t += max(dd, 0.045);
    if (t > 18.0) { break; }
  }
  if (!found) {
    let a0 = smoothstep(0.15, -0.15, d2) * 0.7;
    return vec4f(vec3f(0.34, 0.36, 0.75) * 0.35, a0);
  }
  let e = 0.12;
  let d0 = mar6_crawler_sd3(pos, hd, ph);
  let nrm = normalize(vec3f(
    mar6_crawler_sd3(pos + vec3f(e, 0.0, 0.0), hd, ph) - d0,
    mar6_crawler_sd3(pos + vec3f(0.0, e, 0.0), hd, ph) - d0,
    mar6_crawler_sd3(pos + vec3f(0.0, 0.0, e), hd, ph) - d0
  ));
  let L = normalize(vec3f(-0.55, -0.75, -0.50));
  var sh = 1.0;
  var ts = 0.35;
  for (var si = 0; si < 7; si++) {
    let sd = mar6_crawler_sd3(pos + L * ts, hd, ph);
    sh = min(sh, clamp(sd / (ts * 0.22), 0.0, 1.0));
    ts += clamp(sd, 0.18, 1.6);
    if (ts > 9.0) { break; }
  }
  sh = clamp(sh, 0.0, 1.0);
  var ao = 0.0;
  for (var ki = 1; ki <= 3; ki++) {
    let ha = f32(ki) * 0.55;
    ao += clamp(mar6_crawler_sd3(pos + nrm * ha, hd, ph) / ha, 0.0, 1.0);
  }
  ao = clamp(ao / 3.0, 0.0, 1.0);
  let dif = clamp(dot(nrm, L), 0.0, 1.0);
  let V = vec3f(0.0, 0.0, -1.0);
  let Hh = normalize(L + V);
  let spe = pow(clamp(dot(nrm, Hh), 0.0, 1.0), 48.0);
  let fre = pow(1.0 - clamp(dot(nrm, V), 0.0, 1.0), 3.0);
  var lum = 0.14 + dif * (0.35 + 0.65 * sh) * 0.95;
  lum *= 0.45 + 0.55 * ao;
  let hq = pos.xy;
  var color = mod_ramp2(vec3f(0.10, 0.10, 0.28), vec3f(0.34, 0.36, 0.75), vec3f(0.78, 0.82, 1.0), clamp(lum, 0.0, 1.0));
  let bobC = sin(ph * 18.85) * 0.4;
  let bodyAC = rotate(vec2f(-5.0, bobC), hd);
  let bodyBC = rotate(vec2f(5.0, -bobC), hd);
  let ringv = smoothstep(0.35, 0.15, abs(fract(length(hq - bodyAC) * 0.33) - 0.5)) * smoothstep(5.0, 3.5, length(hq - bodyAC))
            + smoothstep(0.35, 0.15, abs(fract(length(hq - bodyBC) * 0.33) - 0.5)) * smoothstep(4.5, 3.0, length(hq - bodyBC));
  color *= 1.0 - 0.30 * clamp(ringv, 0.0, 1.0);
  color += vec3f(0.18, 0.10, 0.30) * fre;
  color += vec3f(1.4, 1.4, 1.3) * spe * (0.3 + 0.7 * sh) * 0.9;
  color += vec3f(0.28, 0.30, 0.90) * exp(d2 * 0.85) * 0.30;
  color += vec3f(0.10, 0.13, 0.20) * fre * 0.55;
  let headE = rotate(vec2f(9.5, -bobC - 1.0), hd);
  let eyeP = headE + rotate(vec2f(0.8, -0.8), hd);
  color = mix(color, vec3f(0.02, 0.02, 0.06), smoothstep(0.70, 0.42, length(hq - eyeP)));
  color += vec3f(1.5) * smoothstep(0.42, 0.14, length(hq - eyeP - vec2f(0.35, -0.35)));
  let alpha = smoothstep(0.15, -0.15, d2);
  return vec4f(color, alpha);
}

terra_arena.wgsl:
fn visual_terra_arena(uv: vec2f, sdf: f32, col: vec4f, time: f32, p: vec4f, behind: vec4f) -> vec4f {
  var c = vec3f(0.040, 0.050, 0.058);
  let h = fbm(uv * 3.0 + vec2f(2.7, 1.3), 4);
  let h2 = fbm(uv * 3.0 + vec2f(2.76, 1.26), 4);
  c += vec3f(0.028, 0.036, 0.026) * h;
  c += vec3f(0.020, 0.024, 0.016) * clamp((h2 - h) * 12.0, 0.0, 1.0);
  let m = fbm(uv * 5.0 - vec2f(1.1, 3.3), 3);
  c = mix(c, vec3f(0.040, 0.078, 0.048), smoothstep(0.55, 0.75, m) * 0.65);
  let cl = fbm(uv * 1.8 + vec2f(time * 0.010, time * 0.004), 3);
  c *= 0.82 + 0.30 * smoothstep(0.35, 0.75, cl);
  let rdir = normalize(vec2f(0.55, 0.83));
  let across = uv.x * rdir.y - uv.y * rdir.x;
  let along = dot(uv, rdir);
  let ray = pow(max(fbm(vec2f(across * 7.0, along * 1.1 - time * 0.04), 3), 0.0), 3.0);
  c += vec3f(0.28, 0.31, 0.24) * ray * smoothstep(1.2, -0.9, along) * 0.5;
  let g = uv * 40.0;
  let cell = floor(g);
  let hh = hash21(cell);
  if (hh > 0.9984) {
    let fp = fract(g) - 0.5;
    let tw = 0.5 + 0.5 * sin(time * (1.0 + hh * 3.0) + hh * 40.0);
    c += vec3f(0.5, 0.7, 0.4) * exp(-dot(fp, fp) * 30.0) * tw * 0.7;
  }
  c *= 1.0 - 0.30 * dot(uv * 0.8, uv * 0.8);
  return vec4f(c, 1.0);
}

terra_moss.wgsl:
fn visual_terra_moss(uv: vec2f, sdf: f32, col: vec4f, time: f32, p: vec4f, behind: vec4f) -> vec4f {
  let full = clamp(p.x, 0.0, 1.0);
  if (full < 0.03) { return vec4f(0.0); }
  let d = length(uv);
  let wob = 0.75 + 0.35 * fbm(uv * 3.5 + vec2f(p.y * 9.0, 0.0), 3);
  let r = (0.22 + 0.62 * full) * wob;
  let body = smoothstep(r, r - 0.28, d);
  if (body < 0.01) { return vec4f(0.0); }
  var c = mix(vec3f(0.05, 0.22, 0.12), vec3f(0.16, 0.55, 0.30), body);
  let pulse = 0.85 + 0.15 * sin(time * 1.3 + p.y * 20.0);
  c += vec3f(0.25, 0.85, 0.45) * exp(-d * d / max(r * r, 0.01) * 2.5) * 0.5 * pulse * full;
  let sp = fbm(uv * 9.0 + vec2f(p.y * 31.0, time * 0.05), 3);
  c += vec3f(0.4, 1.0, 0.6) * step(0.72, sp) * 0.35 * full;
  return vec4f(c, body * (0.55 + 0.45 * full));
}

terra_grazer.wgsl:
fn terra_grazer_sd(q: vec2f, hd: f32, ph: f32, fear: f32) -> f32 {
  let bob = sin(ph * 12.566) * 0.5;
  let hip = rotate(vec2f(-7.0, bob * 0.5), hd);
  let chest = rotate(vec2f(6.0, bob), hd);
  let head = rotate(vec2f(13.0, -3.0 + bob), hd);
  let wag = sin(ph * 5.65) * 1.4;
  let tail = rotate(vec2f(-15.0, -2.0 - bob + wag), hd);
  var d = mod_cap(q, hip, chest, 2.3);
  d = opSmoothUnion(d, mod_cap(q, chest, head, 1.3), 1.3);
  d = opSmoothUnion(d, length(q - head) - 2.4, 1.0);
  d = opSmoothUnion(d, length(q - (head + rotate(vec2f(2.5, 0.5), hd))) - 1.1, 0.9);
  d = opSmoothUnion(d, mod_cap(q, hip, tail, 0.8), 1.2);
  // ears fold back with fear
  let earA = head + rotate(vec2f(-0.6 - fear * 1.6, -3.2 + fear * 1.2), hd);
  let earB = head + rotate(vec2f(1.2 - fear * 1.6, -3.0 + fear * 1.2), hd);
  d = opSmoothUnion(d, mod_cap(q, head, earA, 0.5), 0.5);
  d = opSmoothUnion(d, mod_cap(q, head, earB, 0.45), 0.5);
  for (var i = 0; i < 4; i++) {
    let front = f32(i / 2);
    let baseL = mix(vec2f(-7.0, bob * 0.5), vec2f(6.0, bob), front);
    var offs = array<f32, 4>(0.0, 0.5, 0.25, 0.75);
    let g = mod_gait(ph + offs[i], 0.6, 4.5, 2.6);
    let fx = baseL.x + g.x;
    let footL = vec2f(fx, 10.0 + g.y);
    let kneeL = vec2f((baseL.x + fx) * 0.5 + 1.5, (baseL.y + footL.y) * 0.5 - 1.5);
    let base = rotate(baseL, hd);
    let knee = rotate(kneeL, hd);
    let foot = rotate(footL, hd);
    d = opSmoothUnion(d, mod_cap(q, base, knee, 0.95), 0.9);
    d = opSmoothUnion(d, mod_cap(q, knee, foot, 0.68), 0.7);
    d = opSmoothUnion(d, length(q - foot) - 0.85, 0.5);
  }
  return d;
}
fn visual_terra_grazer(uv: vec2f, sdf: f32, col: vec4f, time: f32, p: vec4f, behind: vec4f) -> vec4f {
  let life = clamp(p.w, 0.0, 1.0);
  if (life < 0.02) { return vec4f(0.0); }
  let c = uv * 22.0;
  let hd = p.x; let ph = p.y; let fear = clamp(p.z, 0.0, 1.0);
  let d = terra_grazer_sd(c, hd, ph, fear);
  if (d > 3.0) {
    let ds = terra_grazer_sd(c - vec2f(3.5, 4.5), hd, ph, fear);
    return vec4f(vec3f(0.0), smoothstep(2.2, -1.2, ds) * 0.38 * life);
  }
  let e = 0.25;
  let dx = terra_grazer_sd(c + vec2f(e, 0.0), hd, ph, fear) - d;
  let dy = terra_grazer_sd(c + vec2f(0.0, e), hd, ph, fear) - d;
  let n = normalize(vec3f(-dx / e, -dy / e, 1.30));
  let L = normalize(vec3f(-0.5, -0.85, 0.55));
  var lum = clamp((dot(n, L) + 0.35) / 1.35, 0.0, 1.0) * 0.95 + 0.12;
  var color = mod_ramp(vec3f(0.20, 0.16, 0.08), vec3f(0.62, 0.55, 0.30), vec3f(0.96, 0.92, 0.68), clamp(lum, 0.0, 1.0));
  // heritable tint — the field's color carries the lineage
  color *= mix(vec3f(1.0), col.rgb * 1.6, 0.4);
  let bl = rotate(c, -hd);
  color *= 0.86 + 0.26 * fbm(bl * vec2f(0.9, 3.0) + vec2f(3.0, 7.0), 3);
  color += vec3f(1.2, 1.15, 1.0) * pow(max(dot(n, normalize(L + vec3f(0.0, 0.0, 1.0))), 0.0), 40.0) * 0.3;
  color *= 1.0 - 0.28 * smoothstep(-1.0, 0.0, d);
  color = mix(color, vec3f(1.0, 0.95, 0.9), fear * 0.12);
  let bobE = sin(ph * 12.566) * 0.5;
  let headE = rotate(vec2f(13.0, -3.0 + bobE), hd);
  let eyeP = headE + rotate(vec2f(1.0, -0.9), hd);
  color = mix(color, vec3f(0.05, 0.03, 0.01), smoothstep(0.70 + fear * 0.15, 0.42, length(c - eyeP)));
  color += vec3f(1.3) * smoothstep(0.42, 0.15, length(c - eyeP - vec2f(0.35, -0.35)));
  let alpha = smoothstep(0.15, -0.15, d) * life;
  return vec4f(color, alpha);
}

terra_pred.wgsl:
fn terra_pred_sd(q: vec2f, hd: f32, ph: f32, ra: f32, lunge: f32) -> f32 {
  let head = rotate(vec2f(15.0, sin(ph * 8.8) * 1.2), hd);
  var d = length(q - head) - 2.8;
  var prev = head;
  for (var i = 1; i < 10; i++) {
    let fi = f32(i);
    let cur = rotate(vec2f(15.0 - fi * 3.3, sin(ph * 8.8 - fi * 0.85) * (1.6 + fi * 0.35)), hd);
    let r = max(2.4 - fi * 0.20, 0.5);
    let ab = cur - prev;
    let h = clamp(dot(q - prev, ab) / max(dot(ab, ab), 0.0001), 0.0, 1.0);
    d = opSmoothUnion(d, length(q - prev - ab * h) - r, 1.1);
    prev = cur;
  }
  if (lunge > 0.1) {
    let dir = vec2f(cos(ra), sin(ra));
    let tip = head + dir * (2.0 + 5.0 * lunge);
    let side = vec2f(-dir.y, dir.x);
    d = min(d, mod_cap(q, head + dir * 1.5, tip, 0.4));
    d = min(d, mod_cap(q, tip, tip + dir * 1.5 + side * 1.0, 0.3));
    d = min(d, mod_cap(q, tip, tip + dir * 1.5 - side * 1.0, 0.3));
  }
  return d;
}
fn visual_terra_pred(uv: vec2f, sdf: f32, col: vec4f, time: f32, p: vec4f, behind: vec4f) -> vec4f {
  let c = uv * 22.0;
  let hd = p.x; let ph = p.y; let ra = p.z; let lunge = clamp(p.w, 0.0, 1.0);
  let d = terra_pred_sd(c, hd, ph, ra, lunge);
  if (d > 3.0) {
    let ds = terra_pred_sd(c - vec2f(3.5, 4.5), hd, ph, ra, lunge);
    return vec4f(vec3f(0.0), smoothstep(2.2, -1.2, ds) * 0.40);
  }
  let e = 0.25;
  let dx = terra_pred_sd(c + vec2f(e, 0.0), hd, ph, ra, lunge) - d;
  let dy = terra_pred_sd(c + vec2f(0.0, e), hd, ph, ra, lunge) - d;
  let n = normalize(vec3f(-dx / e, -dy / e, 1.30));
  let L = normalize(vec3f(-0.5, -0.85, 0.55));
  var lum = clamp((dot(n, L) + 0.35) / 1.35, 0.0, 1.0) * 0.95 + 0.12;
  var color = mod_ramp(vec3f(0.22, 0.05, 0.06), vec3f(0.62, 0.16, 0.14), vec3f(1.0, 0.55, 0.38), clamp(lum, 0.0, 1.0));
  // dorsal banding
  color *= 0.80 + 0.25 * sin(length(c) * 1.4 + ph * 8.8);
  color += vec3f(1.4, 0.9, 0.7) * pow(max(dot(n, normalize(L + vec3f(0.0, 0.0, 1.0))), 0.0), 40.0) * 0.4;
  color *= 1.0 - 0.28 * smoothstep(-1.0, 0.0, d);
  color = mix(color, vec3f(1.3, 0.5, 0.3), lunge * 0.25);
  let headE = rotate(vec2f(15.0, sin(ph * 8.8) * 1.2), hd);
  let eyeP = headE + rotate(vec2f(1.1, -1.1), hd);
  color = mix(color, vec3f(0.9, 0.75, 0.1), smoothstep(0.70, 0.42, length(c - eyeP)));
  color = mix(color, vec3f(0.05, 0.02, 0.01), smoothstep(0.35, 0.18, length(c - eyeP)));
  let alpha = smoothstep(0.15, -0.15, d);
  return vec4f(color, alpha);
}

chorus_arena.wgsl:
fn visual_chorus_arena(uv: vec2f, sdf: f32, col: vec4f, time: f32, p: vec4f, behind: vec4f) -> vec4f {
  var c = vec3f(0.010, 0.012, 0.028);
  for (var i = 0; i < 2; i++) {
    let fi = f32(i);
    let sc = 16.0 + fi * 28.0;
    let sp = uv * sc + vec2f(time * (0.008 + fi * 0.01), fi * 7.3);
    let cell = floor(sp);
    let h = hash21(cell + fi * 13.0);
    let fp = fract(sp) - 0.5;
    let star = step(0.986, h) * smoothstep(0.22, 0.02, length(fp));
    c += vec3f(0.55, 0.65, 0.85) * star * (0.3 + 0.4 * sin(time * (0.8 + h * 2.0) + h * 40.0));
  }
  let q = uv * vec2f(1.6, 3.2);
  let band1 = fbm(q + vec2f(time * 0.015, uv.x * 0.6), 3);
  let ribbon1 = exp(-pow((uv.y + 0.35 - band1 * 0.35) * 3.2, 2.0));
  c += vec3f(0.05, 0.22, 0.16) * ribbon1 * (0.55 + 0.45 * sin(time * 0.11));
  let band2 = fbm(q * 1.7 - vec2f(time * 0.01, 0.0), 3);
  let ribbon2 = exp(-pow((uv.y - 0.45 - band2 * 0.28) * 3.6, 2.0));
  c += vec3f(0.10, 0.06, 0.22) * ribbon2;
  c += vec3f(0.045, 0.02, 0.09) * fbm(uv * 2.2 + vec2f(0.0, time * 0.006), 3);
  c *= 1.0 - 0.45 * dot(uv * 0.85, uv * 0.85);
  return vec4f(c, 1.0);
}

chorus_star.wgsl:
fn visual_chorus_star(uv: vec2f, sdf: f32, col: vec4f, time: f32, p: vec4f, behind: vec4f) -> vec4f {
  let tier = p.x;
  let prog = p.y;
  let flash = clamp(p.z, 0.0, 1.0);
  let bloom = clamp(p.w, 0.0, 1.0);
  let d = length(uv);
  let ang = atan2(uv.y, uv.x);
  var c = vec3f(0.0);
  let tt = clamp((tier - 1.0) / 4.0, 0.0, 1.0);
  let core = mix(vec3f(1.4, 0.95, 0.45), vec3f(0.8, 1.1, 1.5), tt);
  let r = 0.13 + tier * 0.032;
  c += core * exp(-d * d / (r * r) * 2.2) * (2.2 + flash * 3.5);
  c += core * 0.35 * exp(-d * 3.2);
  let ray = pow(0.5 + 0.5 * sin(ang * 6.0 + time * 0.3), 6.0);
  c += core * ray * exp(-d * 3.5) * 0.5;
  // progress arc — fills clockwise from the top
  var a2 = atan2(uv.x, -uv.y);
  if (a2 < 0.0) { a2 += 6.28318; }
  let arcOn = step(a2, prog * 6.28318);
  let arc = exp(-pow((d - 0.62) * 26.0, 2.0));
  c += mix(vec3f(0.12, 0.16, 0.24), vec3f(1.2, 0.9, 0.3) * 2.0, arcOn) * arc;
  // one dashed ring per tier climbed
  for (var i = 0; i < 5; i++) {
    let fi = f32(i);
    if (fi < tier - 0.5) {
      let rr = 0.28 + fi * 0.075;
      let dash = 0.6 + 0.4 * sin(ang * 10.0 - time * (0.4 + fi * 0.15));
      c += core * exp(-pow((d - rr) * 40.0, 2.0)) * 0.35 * dash;
    }
  }
  if (bloom > 0.001) {
    let br = (1.0 - bloom) * 1.05;
    c += vec3f(2.5, 2.2, 1.6) * exp(-pow((d - br) * 9.0, 2.0)) * bloom * 2.0;
    c += vec3f(3.0) * exp(-d * d * 3.0) * bloom;
  }
  let a = clamp(exp(-d * d * 1.8) * 1.3 + arc * 0.8 + bloom * 0.5, 0.0, 1.0) * smoothstep(1.05, 0.9, d);
  return vec4f(c, a);
}

chorus_mote.wgsl:
fn visual_chorus_mote(uv: vec2f, sdf: f32, col: vec4f, time: f32, p: vec4f, behind: vec4f) -> vec4f {
  let carried = clamp(p.x, 0.0, 1.0);
  let d = length(uv);
  let tw = 0.7 + 0.3 * sin(time * (2.5 + p.y * 3.0) + p.y * 40.0);
  var c = vec3f(1.3, 0.85, 0.3) * exp(-d * d * 11.0) * 2.0 * tw;
  c += vec3f(1.2, 0.6, 0.15) * exp(-d * d * 3.5) * 0.55;
  c = mix(c, c * vec3f(0.8, 1.05, 1.3), carried * 0.5);
  let a = clamp(exp(-d * d * 4.5) * 1.4, 0.0, 1.0) * smoothstep(1.05, 0.75, d);
  return vec4f(c, a);
}

chorus_doubt.wgsl:
fn visual_chorus_doubt(uv: vec2f, sdf: f32, col: vec4f, time: f32, p: vec4f, behind: vec4f) -> vec4f {
  if (p.w > 0.5) { return vec4f(0.0); }
  let d = length(uv);
  let ang = atan2(uv.y, uv.x);
  let wob = 0.75 + 0.4 * vnoise(vec2f(ang * 2.0 + p.z * 12.0, time * 2.6));
  var c = vec3f(0.28, 0.05, 0.4) * exp(-d * d * 5.0) * wob * 1.6;
  c += vec3f(0.7, 0.1, 0.35) * exp(-pow((d - 0.55 * wob) * 5.0, 2.0)) * 0.8;
  c = max(c - vec3f(0.3) * exp(-d * d * 26.0), vec3f(0.0));
  if (p.x > 0.5) { c = mix(c, vec3f(0.25, 0.75, 0.95), 0.4 + 0.3 * sin(time * 15.0)); }
  let a = clamp(exp(-d * d * 4.5) * 1.4, 0.0, 1.0) * smoothstep(1.05, 0.8, d);
  return vec4f(c, a);
}

chorus_pulse.wgsl:
fn visual_chorus_pulse(uv: vec2f, sdf: f32, col: vec4f, time: f32, p: vec4f, behind: vec4f) -> vec4f {
  if (p.y < 0.5) { return vec4f(0.0); }
  let t = clamp(p.x, 0.0, 1.0);
  let d = length(uv);
  let rr = t * 0.92;
  let fade = 1.0 - t;
  var c = vec3f(0.5, 1.0, 1.2) * exp(-pow((d - rr) * (26.0 - t * 14.0), 2.0)) * 3.0 * fade;
  c += vec3f(0.3, 0.7, 1.0) * exp(-pow((d - rr * 0.8) * 30.0, 2.0)) * fade * 0.8;
  let a = clamp(exp(-pow((d - rr) * 14.0, 2.0)) * 1.5 * fade, 0.0, 1.0);
  return vec4f(c, a);
}

chorus_voice.wgsl:
fn visual_chorus_voice(uv: vec2f, sdf: f32, col: vec4f, time: f32, p: vec4f, behind: vec4f) -> vec4f {
  let vel = vec2f(p.x, p.y);
  let sp = length(vel);
  var dir = vec2f(0.0);
  if (sp > 1.0) { dir = vel / sp; }
  let d = length(uv);
  var c = vec3f(0.0);
  c += vec3f(1.1, 1.0, 0.75) * exp(-d * d * 20.0) * 2.8;
  c += vec3f(0.35, 0.8, 1.0) * exp(-d * d * 5.0) * 0.9;
  let tl = clamp(sp / 120.0, 0.0, 1.0);
  for (var i = 1; i <= 4; i++) {
    let fi = f32(i);
    let q = uv + dir * fi * 0.26 * tl;
    c += vec3f(0.5, 0.8, 1.0) * exp(-dot(q, q) * (18.0 + fi * 10.0)) * tl * (1.0 - fi * 0.2);
  }
  c = mix(c, vec3f(1.8, 0.3, 0.25), clamp(p.z * 1.5, 0.0, 0.8));
  if (p.w > 0.5) { c *= 0.65 + 0.35 * sin(time * 18.0); }
  let a = clamp(exp(-d * d * 3.5) * 1.5, 0.0, 1.0) * smoothstep(1.05, 0.8, d);
  return vec4f(c, a);
}

chorus_hud.wgsl:
fn visual_chorus_hud(uv: vec2f, sdf: f32, col: vec4f, time: f32, p: vec4f, behind: vec4f) -> vec4f {
  var c = vec3f(0.0);
  var a = 0.0;
  let prog = p.x;
  let carried = p.y;
  let champs = p.z;
  let energy = clamp(p.w, 0.0, 1.0);
  for (var i = 0; i < 5; i++) {
    let q = (uv - vec2f(-0.28 + f32(i) * 0.14, -0.25)) * vec2f(8.0, 3.2);
    let on = select(0.10, 1.0, f32(i) < prog);
    let g = exp(-dot(q, q) * 1.3);
    c += vec3f(1.2, 0.9, 0.35) * g * on;
    a = max(a, g * 0.85);
  }
  for (var i = 0; i < 5; i++) {
    let q = (uv - vec2f(-0.28 + f32(i) * 0.14, 0.45)) * vec2f(10.0, 4.5);
    let on = select(0.08, 1.0, f32(i) < carried);
    let g = exp(-dot(q, q) * 1.5);
    c += vec3f(0.4, 0.9, 1.1) * g * on;
    a = max(a, g * 0.8 * on);
  }
  for (var i = 0; i < 6; i++) {
    let q = (uv - vec2f(-0.86 + f32(i) * 0.09, 0.0)) * vec2f(12.0, 5.0);
    let on = select(0.0, 1.0, f32(i) < champs);
    let g = exp(-dot(q, q) * 1.6);
    c += vec3f(1.4, 1.1, 0.5) * g * on;
    a = max(a, g * 0.9 * on);
  }
  let qb = uv - vec2f(0.62, 0.0);
  let inBar = step(abs(qb.y), 0.16) * step(0.0, qb.x) * step(qb.x, 0.28);
  let fill = step(qb.x, 0.28 * energy);
  c += mix(vec3f(0.08, 0.12, 0.18), vec3f(0.45, 1.0, 1.2), fill) * inBar;
  a = max(a, inBar * 0.75);
  return vec4f(c * 1.3, clamp(a, 0.0, 1.0));
}

lumen_arena.wgsl:
fn visual_lumen_arena(uv: vec2f, sdf: f32, col: vec4f, time: f32, p: vec4f, behind: vec4f) -> vec4f {
  var c = vec3f(0.012, 0.014, 0.030);
  for (var i = 0; i < 2; i++) {
    let fi = f32(i);
    let sc = 18.0 + fi * 26.0;
    let sp = uv * sc + vec2f(time * (0.01 + fi * 0.012), 0.0);
    let cell = floor(sp);
    let h = hash21(cell + fi * 17.0);
    let fp = fract(sp) - 0.5;
    let star = step(0.985, h) * smoothstep(0.25, 0.03, length(fp));
    c += vec3f(0.5, 0.6, 0.8) * star * (0.35 + 0.4 * sin(time * (1.0 + h * 2.0) + h * 50.0));
  }
  c += vec3f(0.05, 0.02, 0.10) * fbm(uv * 2.0 + vec2f(time * 0.008, 0.0), 3);
  c *= 1.0 - 0.5 * dot(uv * 0.8, uv * 0.8);
  return vec4f(c, 1.0);
}

lumen_ember.wgsl:
fn visual_lumen_ember(uv: vec2f, sdf: f32, col: vec4f, time: f32, p: vec4f, behind: vec4f) -> vec4f {
  let d = length(uv);
  let pulse = 0.75 + 0.25 * sin(time * 3.0 + p.w * 20.0);
  var c = vec3f(1.2, 0.75, 0.25) * exp(-d * d * 10.0) * 2.2 * pulse;
  c += vec3f(1.3, 0.5, 0.1) * exp(-d * d * 3.0) * 0.6;
  let ang = atan2(uv.y, uv.x);
  c *= 0.85 + 0.3 * vnoise(vec2f(ang * 2.0 + p.w * 9.0, time * 2.5));
  let a = clamp(exp(-d * d * 4.0) * 1.5, 0.0, 1.0) * smoothstep(1.05, 0.75, d);
  return vec4f(c, a);
}

lumen_maw.wgsl:
fn visual_lumen_maw(uv: vec2f, sdf: f32, col: vec4f, time: f32, p: vec4f, behind: vec4f) -> vec4f {
  let d = length(uv);
  let ang = atan2(uv.y, uv.x);
  let spin = ang + time * 1.4 - d * 5.0;
  let arms = 0.5 + 0.5 * sin(spin * 3.0);
  var c = vec3f(0.16, 0.03, 0.24) * arms * smoothstep(1.0, 0.25, d);
  c *= smoothstep(0.16, 0.4, d);
  let prox = clamp(p.x, 0.0, 1.5);
  c += vec3f(0.9, 0.08, 0.12) * exp(-pow((d - 0.72) * 6.0, 2.0)) * (0.25 + prox);
  c += vec3f(0.35, 0.1, 0.5) * exp(-pow((d - 0.95) * 10.0, 2.0)) * (0.4 + 0.3 * sin(time * 3.0));
  // Stunned: flicker cyan
  if (p.y > 0.5) { c = mix(c, vec3f(0.2, 0.7, 0.9), 0.35 + 0.3 * sin(time * 16.0)); }
  let a = smoothstep(1.05, 0.85, d);
  return vec4f(c * 1.5, a);
}

lumen_shade.wgsl:
fn visual_lumen_shade(uv: vec2f, sdf: f32, col: vec4f, time: f32, p: vec4f, behind: vec4f) -> vec4f {
  if (p.w > 0.5) { return vec4f(0.0); }
  let d = length(uv);
  let ang = atan2(uv.y, uv.x);
  let wob = 0.8 + 0.35 * vnoise(vec2f(ang * 2.0 + p.z * 10.0, time * 3.0));
  var c = vec3f(0.55, 0.06, 0.16) * exp(-d * d * 6.0) * wob * 1.7;
  c += vec3f(0.95, 0.15, 0.3) * exp(-pow((d - 0.55 * wob) * 5.0, 2.0)) * 0.9;
  c = max(c - vec3f(0.35) * exp(-d * d * 30.0), vec3f(0.0));
  let a = clamp(exp(-d * d * 5.0) * 1.4, 0.0, 1.0) * smoothstep(1.05, 0.8, d);
  return vec4f(c, a);
}

lumen_bolt.wgsl:
fn visual_lumen_bolt(uv: vec2f, sdf: f32, col: vec4f, time: f32, p: vec4f, behind: vec4f) -> vec4f {
  if (p.w > 0.5) { return vec4f(0.0); }
  let vel = vec2f(p.x, p.y);
  let sp = length(vel);
  var dir = vec2f(0.0);
  if (sp > 1.0) { dir = vel / sp; }
  let d = length(uv);
  // Hostile = ember-red. Parried = your blue.
  var hot = vec3f(1.3, 0.45, 0.12);
  if (p.z > 0.5) { hot = vec3f(0.3, 0.9, 1.25); }
  var c = hot * exp(-d * d * 16.0) * 2.5;
  for (var i = 1; i <= 3; i++) {
    let q = uv + dir * f32(i) * 0.3;
    c += hot * exp(-dot(q, q) * 24.0) * (1.0 - f32(i) * 0.25) * 0.8;
  }
  let a = clamp(exp(-d * d * 6.0) * 1.5, 0.0, 1.0);
  return vec4f(c, a);
}

lumen_wisp.wgsl:
fn visual_lumen_wisp(uv: vec2f, sdf: f32, col: vec4f, time: f32, p: vec4f, behind: vec4f) -> vec4f {
  let vel = vec2f(p.x, p.y);
  let sp = length(vel);
  var dir = vec2f(0.0);
  if (sp > 1.0) { dir = vel / sp; }
  var c = vec3f(0.0);
  let d = length(uv);
  c += vec3f(0.65, 0.9, 1.0) * exp(-d * d * 18.0) * 2.6;
  c += vec3f(0.2, 0.5, 1.0) * exp(-d * d * 4.0) * 0.9;
  let tl = clamp(sp / 110.0, 0.0, 1.0);
  for (var i = 1; i <= 4; i++) {
    let fi = f32(i);
    let q = uv + dir * fi * 0.28 * tl;
    c += vec3f(0.3, 0.7, 1.0) * exp(-dot(q, q) * (20.0 + fi * 10.0)) * tl * (1.0 - fi * 0.2);
  }
  c = mix(c, vec3f(1.6, 0.25, 0.2), clamp(p.z * 1.6, 0.0, 0.8));
  if (p.w > 0.5) { c *= 0.6 + 0.4 * sin(time * 20.0); }
  let a = clamp(exp(-d * d * 3.0) * 1.5, 0.0, 1.0) * smoothstep(1.05, 0.8, d);
  return vec4f(c, a);
}

lumen_blade.wgsl:
fn visual_lumen_blade(uv: vec2f, sdf: f32, col: vec4f, time: f32, p: vec4f, behind: vec4f) -> vec4f {
  // Blade lies along local +y (hilt at center, tip outward). p.x = swinging.
  let d = sdSegment(uv, vec2f(0.0, 0.02), vec2f(0.0, 0.94));
  let swing = clamp(p.x, 0.0, 1.0);
  var c = vec3f(0.85, 0.97, 1.0) * exp(-d * d * 260.0) * 2.6;
  c += vec3f(0.4, 0.75, 1.0) * exp(-d * d * 38.0) * (0.65 + swing * 0.9);
  let tip = uv - vec2f(0.0, 0.94);
  c += vec3f(1.0) * exp(-dot(tip, tip) * 60.0) * 1.3;
  let a = clamp(exp(-d * d * 28.0) * 1.7, 0.0, 1.0);
  return vec4f(c, a);
}

lumen_hud.wgsl:
fn visual_lumen_hud(uv: vec2f, sdf: f32, col: vec4f, time: f32, p: vec4f, behind: vec4f) -> vec4f {
  var c = vec3f(0.0);
  var a = 0.0;
  let score = p.x;
  let hp = p.y;
  for (var i = 0; i < 3; i++) {
    let q = (uv - vec2f(-0.8 + f32(i) * 0.15, 0.0)) * vec2f(6.0, 2.8);
    let on = select(0.12, 1.0, f32(i) < hp);
    let g = exp(-dot(q, q) * 1.2);
    c += vec3f(1.1, 0.2, 0.3) * g * on;
    a = max(a, g * 0.9);
  }
  for (var i = 0; i < 20; i++) {
    let row = f32(i / 10);
    let colm = f32(i % 10);
    let q = (uv - vec2f(-0.2 + colm * 0.11, (row - 0.5) * 0.5)) * vec2f(9.0, 4.0);
    let on = select(0.08, 1.0, f32(i) < score);
    let g = exp(-dot(q, q) * 1.4);
    c += vec3f(1.1, 0.8, 0.3) * g * on;
    a = max(a, g * 0.8 * on);
  }
  return vec4f(c * 1.4, clamp(a, 0.0, 1.0));
}

substrate.wgsl:
fn visual_substrate(uv: vec2f, sdf: f32, color: vec4f, time: f32, params: vec4f, behind: vec4f) -> vec4f {
  let p = uv * 6.0;
  let n = fbm4(p + time * 0.015);
  let n2 = fbm4(p * 2.3 + vec2f(5.3, 1.7));
  let base = vec3f(0.03, 0.02, 0.01);
  let mid = vec3f(0.06, 0.04, 0.02);
  let light = vec3f(0.09, 0.06, 0.03);
  var soil = mix(base, mid, n);
  soil = mix(soil, light, n2 * 0.4);
  let sp = hash21(floor(uv * 150.0));
  let sparkle = step(0.99, sp) * 0.12;
  soil = soil + vec3f(sparkle * 0.5, sparkle * 0.4, sparkle * 0.2);
  let rootN = noise(uv * 30.0 + vec2f(0.0, time * 0.05));
  let roots = smoothstep(0.48, 0.5, rootN) * smoothstep(0.54, 0.52, rootN);
  soil = soil + vec3f(roots * 0.03, roots * 0.025, roots * 0.01);
  let edge = smoothstep(0.0, 2.0, -sdf);
  return vec4f(soil, edge);
}

spore.wgsl:
fn visual_spore(uv: vec2f, sdf: f32, color: vec4f, time: f32, params: vec4f, behind: vec4f) -> vec4f {
  let center = vec2f(0.5, 0.5);
  let d = distance(uv, center);
  let angle = atan2(uv.y - 0.5, uv.x - 0.5);
  let nd = fbm4(vec2f(angle * 2.0 + time * 0.3, d * 4.0)) * 0.06;
  let bodyR = 0.22 + nd + sin(angle * 5.0 + time * 0.8) * 0.015;
  let body = smoothstep(bodyR, bodyR - 0.03, d);
  let coreGlow = exp(-d * d * 50.0);
  let pulse = sin(time * 1.5) * 0.5 + 0.5;
  let bodyColor = vec3f(0.12, 0.06, 0.18);
  let coreColor = vec3f(0.1, 0.9, 0.6);
  let glowColor = vec3f(0.0, 1.2, 0.7);
  let tex = fbm4(uv * 12.0 + time * 0.08);
  var col = mix(bodyColor, bodyColor * 1.4, tex) * body;
  col = col + coreColor * coreGlow * (0.6 + pulse * 0.4);
  var tendrils = 0.0;
  for (var i = 0; i < 8; i = i + 1) {
    let a = f32(i) * 0.7854 + time * 0.15;
    let dir = vec2f(cos(a), sin(a));
    let rel = uv - center;
    let proj = dot(rel, dir);
    let perp = abs(dot(rel, vec2f(-dir.y, dir.x)));
    let wobble = noise(vec2f(proj * 15.0, f32(i))) * 0.006;
    let tw = 0.006 + 0.003 * sin(proj * 20.0 + time);
    let tm = smoothstep(tw, tw * 0.2, perp - wobble);
    let tl = smoothstep(0.0, 0.01, proj) * smoothstep(0.42, 0.3, proj);
    tendrils = tendrils + tm * tl;
  }
  tendrils = min(tendrils, 1.0);
  col = col + glowColor * tendrils * 0.35;
  col = col + glowColor * exp(-d * 7.0) * 0.2 * pulse;
  let alpha = max(body, max(tendrils * 0.7, coreGlow * 0.4));
  let edge = smoothstep(0.0, 0.01, -sdf);
  return vec4f(col, alpha * edge);
}

hypha.wgsl:
fn visual_hypha(uv: vec2f, sdf: f32, color: vec4f, time: f32, params: vec4f, behind: vec4f) -> vec4f {
  let seed = params.x + 0.5;
  let center = vec2f(0.5, 0.5);
  var alpha = 0.0;
  for (var i = 0; i < 5; i = i + 1) {
    let fi = f32(i);
    let a = fi * 1.2566 + seed * 6.2832;
    let dir = vec2f(cos(a), sin(a));
    let perp = vec2f(-dir.y, dir.x);
    let rel = uv - center;
    let along = dot(rel, dir);
    let across = dot(rel, perp);
    let w1 = noise(vec2f(along * 10.0 + seed * 7.0, fi * 3.0)) * 0.025;
    let w2 = noise(vec2f(along * 22.0 + seed * 13.0, fi * 5.0)) * 0.01;
    let wobbled = abs(across - w1 - w2);
    let thick = mix(0.009, 0.002, smoothstep(0.0, 0.4, along));
    let m = smoothstep(thick, thick * 0.15, wobbled);
    let lenM = smoothstep(-0.01, 0.02, along) * smoothstep(0.43, 0.33, along);
    alpha = alpha + m * lenM;
    let bp = 0.12 + hash11(seed + fi) * 0.12;
    let ba = a + (hash11(seed + fi + 10.0) - 0.5) * 1.2;
    let bd = vec2f(cos(ba), sin(ba));
    let bp2 = vec2f(-bd.y, bd.x);
    let bOrigin = center + dir * bp;
    let bRel = uv - bOrigin;
    let bAlong = dot(bRel, bd);
    let bAcross = dot(bRel, bp2);
    let bw = noise(vec2f(bAlong * 15.0 + seed * 11.0, fi * 7.0)) * 0.015;
    let bDist = abs(bAcross - bw);
    let bThick = mix(0.005, 0.001, smoothstep(0.0, 0.2, bAlong));
    let bm = smoothstep(bThick, bThick * 0.15, bDist);
    let bl = smoothstep(-0.01, 0.01, bAlong) * smoothstep(0.22, 0.12, bAlong);
    alpha = alpha + bm * bl * 0.8;
  }
  alpha = min(alpha, 1.0);
  let hCol = vec3f(0.92, 0.87, 0.76);
  let tipG = exp(-distance(uv, center) * 5.0) * 0.1;
  let col = hCol + vec3f(0.0, tipG, tipG * 0.6);
  let edge = smoothstep(0.0, 0.01, -sdf);
  return vec4f(col * alpha, alpha * edge);
}

nutrient.wgsl:
fn visual_nutrient(uv: vec2f, sdf: f32, color: vec4f, time: f32, params: vec4f, behind: vec4f) -> vec4f {
  let center = vec2f(0.5, 0.5);
  let d = distance(uv, center);
  let angle = atan2(uv.y - 0.5, uv.x - 0.5);
  let nr = noise(vec2f(angle * 2.5 + params.x * 4.0, time * 0.3)) * 0.07;
  let radius = 0.25 + nr;
  let body = smoothstep(radius, radius - 0.04, d);
  let innerGlow = exp(-d * d * 35.0);
  let pulse = sin(time * 2.0 + params.x * 6.28) * 0.5 + 0.5;
  let bodyColor = vec3f(0.55, 0.35, 0.08);
  let glowColor = vec3f(1.0, 0.7, 0.15);
  let tex = fbm4(uv * 10.0 + params.x);
  var col = bodyColor * body * (0.6 + tex * 0.4);
  col = col + glowColor * innerGlow * (0.4 + pulse * 0.3);
  let alpha = max(body, innerGlow * 0.5);
  let edge = smoothstep(0.0, 0.01, -sdf);
  return vec4f(col, alpha * edge);
}

mushroom.wgsl:
fn visual_mushroom(uv: vec2f, sdf: f32, color: vec4f, time: f32, params: vec4f, behind: vec4f) -> vec4f {
  let cx = 0.5;
  let stemTaper = smoothstep(0.45, 0.8, uv.y);
  let stemHalfW = 0.065 - stemTaper * 0.02;
  let stemDist = abs(uv.x - cx) - stemHalfW;
  let inStem = smoothstep(0.005, 0.0, stemDist) * smoothstep(0.44, 0.46, uv.y) * smoothstep(0.81, 0.79, uv.y);
  let capCenter = vec2f(cx, 0.44);
  let capUV = (uv - capCenter) / vec2f(0.26, 0.16);
  let capDist = length(capUV);
  let rawCap = smoothstep(1.0, 0.93, capDist);
  let inCap = rawCap * smoothstep(0.52, 0.46, uv.y);
  let gillRegion = smoothstep(0.44, 0.5, uv.y) * smoothstep(0.58, 0.5, uv.y);
  let gillX = smoothstep(0.22, 0.08, abs(uv.x - cx));
  let gillAngle = atan2(uv.y - 0.5, uv.x - cx);
  let gillLines = pow(sin(gillAngle * 20.0) * 0.5 + 0.5, 3.0);
  let gills = gillRegion * gillX * gillLines;
  let spotN = noise(uv * 7.0 + params.x * 3.0);
  let spots = smoothstep(0.62, 0.68, spotN) * inCap;
  let stemColor = vec3f(0.75, 0.7, 0.6);
  let capColor = vec3f(0.1, 0.25, 0.15);
  let glowColor = vec3f(0.15, 0.95, 0.45);
  let gillColor = vec3f(0.5, 0.45, 0.35);
  let pulse = sin(time * 1.0 + params.x * 6.28) * 0.5 + 0.5;
  var col = stemColor * inStem;
  col = col + capColor * inCap;
  col = col + gillColor * gills * 0.4;
  col = col + glowColor * spots * (0.7 + pulse * 0.5);
  let ambD = distance(uv, vec2f(cx, 0.48));
  let ambGlow = exp(-ambD * ambD * 12.0) * 0.12;
  col = col + glowColor * ambGlow * pulse;
  let alpha = max(max(inStem, inCap), max(gills * 0.6, ambGlow));
  let edge = smoothstep(0.0, 0.01, -sdf);
  return vec4f(col, alpha * edge);
}

fable_vista.wgsl:
// ═══════════════════════════════════════════════════════════════
// FABLE VISTA — golden hour mountain lake
// Raymarched eroded-fractal terrain, animated water with true
// reflections, aerial perspective, sun-kissed clouds.
// Perf: LOD octaves by distance, ceiling-capped rays, lean shadows.
// ═══════════════════════════════════════════════════════════════

// Value noise with analytic derivatives (quintic interpolation).
// Returns (value in [-1,1], d/dx, d/dy).
fn tr_noised(x: vec2f) -> vec3f {
  let p = floor(x);
  let f = fract(x);
  let u = f * f * f * (f * (f * 6.0 - 15.0) + 10.0);
  let du = 30.0 * f * f * (f * (f - 2.0) + 1.0);
  let a = hash21(p);
  let b = hash21(p + vec2f(1.0, 0.0));
  let c = hash21(p + vec2f(0.0, 1.0));
  let d = hash21(p + vec2f(1.0, 1.0));
  let k1 = b - a;
  let k2 = c - a;
  let k4 = a - b - c + d;
  let val = a + k1 * u.x + k2 * u.y + k4 * u.x * u.y;
  let der = du * vec2f(k1 + k4 * u.y, k2 + k4 * u.x);
  return vec3f(val * 2.0 - 1.0, der.x * 2.0, der.y * 2.0);
}

// Eroded fractal terrain — derivative-damped fbm. Steep slopes
// suppress high frequencies, which reads as water erosion.
fn tr_terrain(p_in: vec2f, octaves: i32) -> f32 {
  var p = p_in * 0.0016;
  var a = 0.0;
  var b = 1.0;
  var d = vec2f(0.0);
  for (var i = 0; i < octaves; i++) {
    let n = tr_noised(p);
    d += n.yz;
    // First octaves ridged — connected alpine spines instead of soft dunes
    var v = n.x;
    if (i < 2) { v = (0.62 - abs(n.x)) * 1.9 - 0.28; }
    a += b * v / (1.0 + dot(d, d));
    b *= 0.5;
    p = mat2x2f(0.8, -0.6, 0.6, 0.8) * p * 2.0;
  }
  var h = a * 240.0;
  // Carved lake basin in front of the camera; taller relief beyond it
  let dv = p_in - vec2f(0.0, 520.0);
  let dist = length(dv);
  h -= 130.0 * exp(-dot(dv, dv) / (480.0 * 480.0));
  h *= 1.0 + 0.34 * smoothstep(700.0, 1900.0, dist);
  return h;
}

const TR_CEIL: f32 = 330.0; // above the highest peak — rays past this never hit

// Heightfield raymarch with interpolated hit refinement and distance LOD.
fn tr_march(ro: vec3f, rd: vec3f, tmax_in: f32, octHi: i32) -> f32 {
  var tmax = tmax_in;
  // Upward rays can only hit until they clear the ceiling
  if (rd.y > 0.001) {
    tmax = min(tmax, (TR_CEIL - ro.y) / rd.y);
    if (tmax < 0.0) { return -1.0; }
  }
  var lh = 0.0;
  var lt = 0.0;
  var t = 1.0;
  for (var i = 0; i < 64; i++) {
    if (t > tmax) { break; }
    let p = ro + rd * t;
    // LOD: fewer octaves far away (detail is sub-pixel there anyway)
    var oct = octHi;
    if (t > 140.0) { oct = octHi - 1; }
    if (t > 650.0) { oct = octHi - 2; }
    let h = p.y - tr_terrain(p.xz, oct);
    if (h < 0.004 * t) {
      return lt + (t - lt) * lh / max(lh - h, 0.001);
    }
    lh = h;
    lt = t;
    t += 0.55 * h + 0.7;
  }
  return -1.0;
}

fn tr_normal(p: vec3f, t: f32) -> vec3f {
  let e = 0.0015 * t + 0.04;
  var oct = 5;
  if (t > 400.0) { oct = 4; }
  return normalize(vec3f(
    tr_terrain(p.xz - vec2f(e, 0.0), oct) - tr_terrain(p.xz + vec2f(e, 0.0), oct),
    2.0 * e,
    tr_terrain(p.xz - vec2f(0.0, e), oct) - tr_terrain(p.xz + vec2f(0.0, e), oct)
  ));
}

// Soft terrain shadow toward the sun — coarse and cheap.
fn tr_shadow(ro: vec3f, rd: vec3f) -> f32 {
  var res = 1.0;
  var t = 10.0;
  for (var i = 0; i < 8; i++) {
    let p = ro + rd * t;
    if (p.y > TR_CEIL) { break; }
    let h = p.y - tr_terrain(p.xz, 2);
    res = min(res, 7.0 * h / t);
    if (res < 0.01) { break; }
    t += clamp(h, 10.0, 90.0);
  }
  return clamp(res, 0.0, 1.0);
}

fn tr_sky(rd: vec3f, sun: vec3f, time: f32) -> vec3f {
  let sundot = clamp(dot(rd, sun), 0.0, 1.0);
  let up = max(rd.y, 0.0);
  // Base gradient: warm haze at horizon, cool blue overhead
  var col = vec3f(0.22, 0.38, 0.64) - up * vec3f(0.18, 0.16, 0.10);
  col = mix(col, vec3f(1.08, 0.60, 0.30), pow(1.0 - up, 6.0) * 0.9);
  // Sun glows (disc comes after clouds so it punches through)
  col += vec3f(1.0, 0.55, 0.25) * 0.42 * pow(sundot, 4.0);
  col += vec3f(1.0, 0.72, 0.42) * 0.45 * pow(sundot, 48.0);
  // Clouds — sparser layer, lit warm, translucent near the sun
  if (rd.y > 0.015) {
    let cuv = (rd.xz / rd.y) * 300.0 + vec2f(time * 2.2, time * 0.6);
    var cov = fbm(cuv * 0.0045, 4);
    cov = smoothstep(0.52, 0.80, cov);
    let shade = fbm(cuv * 0.009 + vec2f(17.3, 9.1), 3);
    var ccol = mix(vec3f(1.06, 0.82, 0.66), vec3f(0.46, 0.44, 0.52), shade * 0.8);
    ccol += vec3f(1.0, 0.55, 0.28) * pow(sundot, 3.0) * 0.5;
    let fade = smoothstep(0.015, 0.14, rd.y);
    let thin = 1.0 - 0.6 * pow(sundot, 8.0);
    col = mix(col, ccol, cov * 0.85 * fade * thin);
  }
  // Sun disc — over the clouds
  col += vec3f(1.2, 0.95, 0.7) * 1.6 * pow(sundot, 1600.0);
  col += vec3f(1.1, 0.8, 0.5) * 0.35 * pow(sundot, 180.0);
  return col;
}

fn tr_fog(col: vec3f, t: f32, rd: vec3f, sun: vec3f) -> vec3f {
  let amt = 1.0 - exp(-pow(t * 0.00022, 1.5));
  let sundot = clamp(dot(rd, sun), 0.0, 1.0);
  let fogc = mix(vec3f(0.50, 0.56, 0.66), vec3f(1.02, 0.70, 0.44), pow(sundot, 5.0));
  return mix(col, fogc, amt);
}

// Terrain surface shading (golden hour palette).
fn tr_shade(p: vec3f, t: f32, rd: vec3f, sun: vec3f, withShadow: bool) -> vec3f {
  let nor = tr_normal(p, t);
  // Materials
  let strata = fbm(p.xz * 0.05, 3);
  var rock = mix(vec3f(0.23, 0.20, 0.18), vec3f(0.38, 0.33, 0.28), strata);
  rock = mix(rock, vec3f(0.30, 0.24, 0.19), fbm(p.xz * 0.013, 2) * 0.7);
  var grass = mix(vec3f(0.10, 0.16, 0.06), vec3f(0.22, 0.26, 0.10), fbm(p.xz * 0.09, 2));
  // Golden-hour dry grass patches
  grass = mix(grass, vec3f(0.34, 0.27, 0.11), fbm(p.xz * 0.021 + vec2f(31.0, 7.0), 2) * 0.55);
  let snow = vec3f(0.86, 0.90, 0.98);
  let slope = nor.y;
  var mat = mix(rock, grass,
    smoothstep(0.62, 0.82, slope) * smoothstep(95.0, 25.0, p.y));
  let snowline = 120.0 + 45.0 * fbm(p.xz * 0.008, 2);
  mat = mix(mat, snow,
    smoothstep(snowline, snowline + 22.0, p.y) * smoothstep(0.42, 0.68, slope));
  // Wet dark band at the shoreline
  mat = mix(vec3f(0.11, 0.095, 0.085), mat, smoothstep(-12.0, -7.5, p.y));
  // Lighting
  var sh = 1.0;
  if (withShadow) { sh = tr_shadow(p + nor * 1.5, sun); }
  let dif = clamp(dot(nor, sun), 0.0, 1.0) * sh;
  let skyl = clamp(0.5 + 0.5 * nor.y, 0.0, 1.0);
  let bounce = clamp(dot(nor, normalize(vec3f(-sun.x, 0.0, -sun.z))), 0.0, 1.0);
  var lin = dif * vec3f(1.35, 0.92, 0.62) * 2.9;
  lin += skyl * vec3f(0.32, 0.42, 0.58) * 0.65;
  lin += bounce * vec3f(0.34, 0.26, 0.18) * 0.30;
  var col = mat * lin;
  // Specular kiss on wet-looking rock and snow
  let hal = normalize(sun - rd);
  let spe = pow(clamp(dot(nor, hal), 0.0, 1.0), 24.0) * dif;
  col += spe * vec3f(1.0, 0.8, 0.6) * 0.25 * smoothstep(0.3, 0.6, strata);
  return tr_fog(col, t, rd, sun);
}

// Animated water height (three scales of drift).
fn tr_waterH(p: vec2f, time: f32) -> f32 {
  var h = vnoise(p * 0.055 + vec2f(time * 0.30, time * 0.16)) * 0.58;
  h += vnoise(p * 0.170 - vec2f(time * 0.24, time * 0.33)) * 0.29;
  h += vnoise(p * 0.520 + vec2f(time * 0.45, -time * 0.27)) * 0.13;
  return h;
}

fn tr_waterNor(p: vec2f, time: f32, dist: f32) -> vec3f {
  // Wave detail flattens with distance to avoid shimmer
  let amp = 1.35 / (1.0 + dist * 0.016);
  let e = 0.9;
  let hC = tr_waterH(p, time);
  let hX = tr_waterH(p + vec2f(e, 0.0), time);
  let hZ = tr_waterH(p + vec2f(0.0, e), time);
  return normalize(vec3f((hC - hX) * amp, e, (hC - hZ) * amp));
}

fn visual_fable_vista(uv: vec2f, sdf: f32, col: vec4f, time: f32, p: vec4f, behind: vec4f) -> vec4f {
  // ── Camera: slow drift across the lake, gentle yaw ──
  let yaw = sin(time * 0.021) * 0.07;
  let waterY = -14.0;
  var ro = vec3f(0.0, waterY + 15.5 + sin(time * 0.12) * 0.35, -130.0);

  var rd = normalize(vec3f(uv.x * 1.30, -uv.y * 1.30 - 0.045, 1.55));
  let cy = cos(yaw);
  let sy = sin(yaw);
  rd = vec3f(cy * rd.x + sy * rd.z, rd.y, -sy * rd.x + cy * rd.z);

  let sun = normalize(vec3f(0.10, 0.145, 0.92));

  // ── Primary ray ──
  var color: vec3f;

  // Water plane intersection first — terrain beyond the water hit can never
  // be visible, so cap the march there (big win for the lower half of frame)
  var tWat = -1.0;
  if (rd.y < -0.001) { tWat = (waterY - ro.y) / rd.y; }
  var tCap = 4200.0;
  if (tWat > 0.0) { tCap = tWat + 1.0; }
  let tTer = tr_march(ro, rd, tCap, 5);

  let hitWater = tWat > 0.0 && (tTer < 0.0 || tWat < tTer);

  if (hitWater) {
    // ── Water: waves, Fresnel, true reflected terrain ──
    let wp = ro + rd * tWat;
    let wn = tr_waterNor(wp.xz, time, tWat);
    var rrd = reflect(rd, wn);
    rrd.y = max(rrd.y, 0.015); // keep reflections above the surface
    rrd = normalize(rrd);

    let fres = 0.03 + 0.97 * pow(1.0 - clamp(dot(-rd, wn), 0.0, 1.0), 5.0);

    // Reflected world (no shadows in reflections — the eye can't tell)
    let rro = vec3f(wp.x, wp.y + 0.15, wp.z);
    var refl: vec3f;
    let tRef = tr_march(rro, rrd, 750.0, 4);
    if (tRef > 0.0) {
      refl = tr_shade(rro + rrd * tRef, tRef + tWat, rrd, sun, false);
    } else {
      refl = tr_sky(rrd, sun, time);
    }

    // Water body: deep teal, slightly lighter in the shallows
    let deep = vec3f(0.015, 0.058, 0.062);
    let body = mix(deep, vec3f(0.03, 0.10, 0.10), vnoise(wp.xz * 0.01) * 0.5);
    color = mix(body, refl, fres);

    // Sun glint — sharp specular off the wave normals
    let glint = pow(clamp(dot(rrd, sun), 0.0, 1.0), 420.0);
    color += vec3f(1.2, 0.9, 0.6) * glint * fres * 4.0;

    color = tr_fog(color, tWat, rd, sun);
  } else if (tTer > 0.0) {
    color = tr_shade(ro + rd * tTer, tTer, rd, sun, true);
  } else {
    color = tr_sky(rd, sun, time);
  }

  // Output linear HDR — the engine post pass applies ACES + bloom itself.
  // Slight exposure lift so post-ACES mids sit right on screen.
  color *= 1.55;

  return vec4f(color, 1.0);
}

cradle_window.wgsl:
// ═══════════════════════════════════════════════════════════════
// CRADLE WINDOW — a framed night sky that is the Mirror's inner
// weather, hanging over the golden vista.
//   p.x = star density   (vocabulary size)
//   p.y = aurora energy  (thread activity)
//   p.z = champion pulse (surges when a new champion is crowned)
//   p.w = dream shift    (hue drift toward violet while dreaming)
// ═══════════════════════════════════════════════════════════════

fn cw_aurora(v: vec2f, time: f32, energy: f32, hueShift: f32) -> vec3f {
  var acc = vec3f(0.0);
  for (var i = 0; i < 3; i++) {
    let fi = f32(i);
    let speed = 0.025 + fi * 0.012;
    let band = fbm(vec2f(v.x * (1.3 + fi * 0.6) + time * speed, fi * 7.31 + time * 0.015), 4);
    let center = 0.06 + fi * 0.17 + (band - 0.5) * 0.55 * energy;
    let width = 0.05 + 0.055 * band + 0.02 * fi;
    let curtain = exp(-pow((v.y - center) / width, 2.0));
    // Vertical ray structure drifting sideways
    let rays = 0.55 + 0.45 * fbm(vec2f(v.x * 9.0 + fi * 3.7 - time * (0.05 + fi * 0.02), time * 0.03), 3);
    let green = vec3f(0.05, 0.85, 0.35);
    let violet = vec3f(0.45, 0.15, 0.85);
    let hue = mix(green, violet, clamp(fi * 0.35 + hueShift, 0.0, 1.0));
    acc += hue * curtain * rays * (0.45 + 0.55 * energy);
  }
  return acc;
}

fn visual_cradle_window(uv: vec2f, sdf: f32, col: vec4f, time: f32, p: vec4f, behind: vec4f) -> vec4f {
  let v = vec2f(uv.x, -uv.y); // compute-path y is inverted; v.y = up
  let starDensity = clamp(p.x, 0.0, 1.0);
  let energy = clamp(p.y, 0.15, 1.6);
  let pulse = clamp(p.z, 0.0, 1.0);
  let dream = clamp(p.w, 0.0, 1.0);
  let hueShift = dream * 0.6 + pulse * 0.25;

  let horizon = -0.34;
  let ridge = horizon + 0.09 + 0.15 * fbm(vec2f(v.x * 2.2 + 13.7, 3.1), 4);

  var c: vec3f;

  if (v.y >= horizon) {
    let sky = clamp((v.y - horizon) / (1.0 - horizon), 0.0, 1.0);
    c = mix(vec3f(0.030, 0.045, 0.085), vec3f(0.005, 0.009, 0.026), sky);
    // Stars — one per grid cell, density from vocabulary
    let sp = v * 46.0;
    let cell = floor(sp);
    let h = hash21(cell);
    let sel = step(1.0 - (0.015 + 0.05 * starDensity), h);
    let fp = fract(sp) - 0.5;
    let pt = smoothstep(0.32, 0.05, length(fp));
    let tw = 0.55 + 0.45 * sin(time * (0.8 + h * 2.4) + h * 61.0);
    c += vec3f(0.85, 0.9, 1.0) * sel * pt * tw * (0.25 + 0.75 * sky);
    // Aurora — the thinking
    let a = cw_aurora(v, time, energy, hueShift);
    c += a * (0.55 + 1.2 * pulse) * smoothstep(horizon, horizon + 0.22, v.y);
    // Black ridgeline, faintly rim-lit by the aurora
    if (v.y < ridge) {
      c = vec3f(0.004, 0.006, 0.012) + a * 0.05;
    }
  } else {
    // Still water remembering the sky
    let wobble = 0.018 * sin(v.y * 42.0 + time * 0.7);
    let rv = vec2f(v.x + wobble, 2.0 * horizon - v.y);
    let a = cw_aurora(rv, time, energy, hueShift);
    let depth = clamp((horizon - v.y) / (1.0 + horizon), 0.0, 1.0);
    c = vec3f(0.007, 0.012, 0.028) + a * 0.42 * (1.0 - depth * 0.75) * (0.55 + 1.2 * pulse);
    let rip = vnoise(vec2f(v.x * 30.0, v.y * 60.0 - time * 0.55));
    c *= 0.85 + 0.30 * rip;
  }

  // Frame: dark bezel with a warm lit edge — a window, not a wall
  let edge = max(abs(uv.x), abs(uv.y));
  c = mix(c, vec3f(0.002, 0.002, 0.004), smoothstep(0.93, 0.962, edge));
  let border = smoothstep(0.962, 0.978, edge) * (1.0 - smoothstep(0.992, 1.0, edge));
  c += vec3f(1.0, 0.60, 0.26) * border * 1.3;

  // Linear HDR out; engine ACES grades it
  let alpha = 1.0 - smoothstep(0.0, 0.5, sdf);
  return vec4f(c * 1.6, alpha);
}

sanct_lib.wgsl:
// day palette: 0 dawn → .25 noon → .5 dusk → .75 night → 1 dawn
fn mod_skycol(t: f32) -> vec3f {
  let dawn = vec3f(1.0, 0.72, 0.45);
  let noon = vec3f(1.0, 0.97, 0.85);
  let dusk = vec3f(1.0, 0.45, 0.30);
  let night = vec3f(0.30, 0.42, 0.72);
  let x = fract(t) * 4.0;
  if (x < 1.0) { return mix(dawn, noon, smoothstep(0.0, 1.0, x)); }
  if (x < 2.0) { return mix(noon, dusk, smoothstep(0.0, 1.0, x - 1.0)); }
  if (x < 3.0) { return mix(dusk, night, smoothstep(0.0, 1.0, x - 2.0)); }
  return mix(night, dawn, smoothstep(0.0, 1.0, x - 3.0));
}
fn mod_bright(t: f32) -> f32 {
  return 0.30 + 0.70 * (0.5 + 0.5 * cos((fract(t) - 0.25) * 6.28318));
}
// arch window SDF in room uv space: rounded-top opening centered x=0
fn mod_arch(p: vec2f) -> f32 {
  let r = 0.26;
  if (p.y > -0.64) {
    let dx = abs(p.x) - r;
    let dy = max(-0.64 - p.y, p.y + 0.30);
    return max(dx, dy);
  }
  return length(vec2f(p.x, p.y + 0.64)) - r;
}
// stained glass: colored panes + leadwork, lit by the sky
fn mod_glass(p: vec2f, dayT: f32) -> vec4f {
  let d = mod_arch(p);
  if (d > 0.0) { return vec4f(0.0); }
  let sky = mod_skycol(dayT);
  let bright = mod_bright(dayT);
  let ci = vec2f(floor((p.x + 0.26) / 0.174), floor((p.y + 0.90) / 0.15));
  let h = hash21(ci * 7.3 + vec2f(2.0, 5.0));
  let tint = hsv2rgb(vec3f(fract(h * 5.7), 0.55, 1.0));
  var col = tint * sky * (0.7 + 1.7 * bright);
  col *= 0.86 + 0.28 * fbm(p * 18.0, 2);
  let night = 1.0 - smoothstep(0.30, 0.55, bright);
  let sh = hash21(floor(p * 90.0));
  let star = step(0.995, sh) * (0.5 + 0.5 * sin(dayT * 700.0 + sh * 40.0));
  col = mix(col, vec3f(0.05, 0.07, 0.13) + tint * 0.10 + vec3f(0.9) * star, night * 0.85);
  let lx = abs(fract((p.x + 0.26) / 0.174) - 0.5);
  let ly = abs(fract((p.y + 0.90) / 0.15) - 0.5);
  let lead = max(step(0.45, lx), step(0.45, ly));
  col = mix(col, vec3f(0.05, 0.05, 0.06), lead);
  col = mix(col, vec3f(0.10, 0.09, 0.08), smoothstep(-0.02, 0.0, d));
  return vec4f(col, 1.0);
}
// cheap glass for light-projection taps: tint + lead, no fbm/stars
fn mod_glass_lite(p: vec2f, dayT: f32) -> vec4f {
  let d = mod_arch(p);
  if (d > 0.0) { return vec4f(0.0); }
  let sky = mod_skycol(dayT);
  let bright = mod_bright(dayT);
  let ci = vec2f(floor((p.x + 0.26) / 0.174), floor((p.y + 0.90) / 0.15));
  let h = hash21(ci * 7.3 + vec2f(2.0, 5.0));
  var col = hsv2rgb(vec3f(fract(h * 5.7), 0.55, 1.0)) * sky * (0.7 + 1.7 * bright);
  let night = 1.0 - smoothstep(0.30, 0.55, bright);
  col = mix(col, vec3f(0.05, 0.07, 0.13), night * 0.85);
  let lx = abs(fract((p.x + 0.26) / 0.174) - 0.5);
  let ly = abs(fract((p.y + 0.90) / 0.15) - 0.5);
  col = mix(col, vec3f(0.05, 0.05, 0.06), max(step(0.45, lx), step(0.45, ly)));
  return vec4f(col, 1.0);
}
// projective window light: for any point, trace back along the sun direction
// to the window plane and sample the ACTUAL stained glass there. The beam is
// the window's own shape extruded along the sun angle; the floor receives the
// stretched pane pattern (leadwork shadows included); edges blur with travel
// (penumbra) and intensity attenuates. Light and window cannot disagree.
fn mod_beams(p: vec2f, dayT: f32) -> vec3f {
  let bright = mod_bright(dayT);
  let sunx = sin(fract(dayT) * 6.28318) * 0.55;
  var ys = array<f32, 3>(-0.82, -0.60, -0.38);
  var acc = vec3f(0.0);
  for (var i = 0; i < 3; i++) {
    let yw = ys[i];
    let travel = p.y - yw;
    if (travel < 0.0) { continue; }
    let xw = p.x - sunx * travel;
    let blur = 0.008 + travel * 0.045;
    let g1 = mod_glass_lite(vec2f(xw - blur, yw), dayT);
    let g2 = mod_glass_lite(vec2f(xw + blur, yw), dayT);
    acc += (g1.rgb * g1.a + g2.rgb * g2.a) * 0.5 * exp(-travel * 0.50);
  }
  return acc * 0.34 * (0.15 + 0.85 * bright);
}

skel6.wgsl:
fn mod_seg2(p: vec2f, a: vec2f, b: vec2f) -> f32 {
  let ab = b - a;
  let h = clamp(dot(p - a, ab) / max(dot(ab, ab), 0.0001), 0.0, 1.0);
  return length(p - a - ab * h);
}
fn mod_cap2(p: vec2f, a: vec2f, b: vec2f, r: f32) -> f32 {
  return mod_seg2(p, a, b) - r;
}
fn mod_ramp2(dark: vec3f, base: vec3f, lite: vec3f, t: f32) -> vec3f {
  let lo = clamp(t * 2.0, 0.0, 1.0);
  let hi = clamp(t * 2.0 - 1.0, 0.0, 1.0);
  return mix(mix(dark, base, lo), lite, hi);
}
fn mod_blink2(time: f32, seed: f32) -> f32 {
  return step(fract(time * 0.31 + seed), 0.06);
}
fn mod_cap3(p: vec3f, a: vec2f, b: vec2f, r: f32) -> f32 {
  let a3 = vec3f(a, 0.0);
  let ab = vec3f(b - a, 0.0);
  let h = clamp(dot(p - a3, ab) / max(dot(ab, ab), 0.0001), 0.0, 1.0);
  return length(p - a3 - ab * h) - r;
}
fn mod_sph3(p: vec3f, c: vec2f, r: f32) -> f32 {
  return length(p - vec3f(c, 0.0)) - r;
}
// Planted gait: phase is in stride CYCLES (advanced by distance traveled).
// Stance (cyc < duty): foot drives linearly back at exactly body speed —
// world-velocity zero, the foot is planted. Swing: eased return with a lift arc.
fn mod_gait(phc: f32, duty: f32, len: f32, lift: f32) -> vec2f {
  let cyc = fract(phc);
  if (cyc < duty) {
    let t = cyc / duty;
    return vec2f(len - 2.0 * len * t, 0.0);
  }
  let t = (cyc - duty) / (1.0 - duty);
  let e = t * t * (3.0 - 2.0 * t);
  return vec2f(-len + 2.0 * len * e, -sin(t * 3.14159) * lift);
}

