fn visual_lumen_arena(uv: vec2f, sdf: f32, col: vec4f, time: f32, p: vec4f, behind: vec4f) -> vec4f {
  var c = vec3f(0.012, 0.014, 0.030);
  for (var i = 0; i < 2; i++) {
    let fi = f32(i);
    let sc = 18.0 + fi * 26.0;
    let sp = uv * sc + vec2f(time * (0.01 + fi * 0.012), 0.0);
    let cell = floor(sp);
    let h = hash21(cell + fi * 17.0);
    let fp = fract(sp) - 0.5;
    let star = step(0.985, h) * smoothstep(0.25, 0.03, length(fp));
    c += vec3f(0.5, 0.6, 0.8) * star * (0.35 + 0.4 * sin(time * (1.0 + h * 2.0) + h * 50.0));
  }
  c += vec3f(0.05, 0.02, 0.10) * fbm(uv * 2.0 + vec2f(time * 0.008, 0.0), 3);
  c *= 1.0 - 0.5 * dot(uv * 0.8, uv * 0.8);
  return vec4f(c, 1.0);
}

fn visual_lumen_ember(uv: vec2f, sdf: f32, col: vec4f, time: f32, p: vec4f, behind: vec4f) -> vec4f {
  let d = length(uv);
  let pulse = 0.75 + 0.25 * sin(time * 3.0 + p.w * 20.0);
  var c = vec3f(1.2, 0.75, 0.25) * exp(-d * d * 10.0) * 2.2 * pulse;
  c += vec3f(1.3, 0.5, 0.1) * exp(-d * d * 3.0) * 0.6;
  let ang = atan2(uv.y, uv.x);
  c *= 0.85 + 0.3 * vnoise(vec2f(ang * 2.0 + p.w * 9.0, time * 2.5));
  let a = clamp(exp(-d * d * 4.0) * 1.5, 0.0, 1.0) * smoothstep(1.05, 0.75, d);
  return vec4f(c, a);
}

fn visual_lumen_maw(uv: vec2f, sdf: f32, col: vec4f, time: f32, p: vec4f, behind: vec4f) -> vec4f {
  let d = length(uv);
  let ang = atan2(uv.y, uv.x);
  let spin = ang + time * 1.4 - d * 5.0;
  let arms = 0.5 + 0.5 * sin(spin * 3.0);
  var c = vec3f(0.16, 0.03, 0.24) * arms * smoothstep(1.0, 0.25, d);
  c *= smoothstep(0.16, 0.4, d);
  let prox = clamp(p.x, 0.0, 1.5);
  c += vec3f(0.9, 0.08, 0.12) * exp(-pow((d - 0.72) * 6.0, 2.0)) * (0.25 + prox);
  c += vec3f(0.35, 0.1, 0.5) * exp(-pow((d - 0.95) * 10.0, 2.0)) * (0.4 + 0.3 * sin(time * 3.0));
  // Stunned: flicker cyan
  if (p.y > 0.5) { c = mix(c, vec3f(0.2, 0.7, 0.9), 0.35 + 0.3 * sin(time * 16.0)); }
  let a = smoothstep(1.05, 0.85, d);
  return vec4f(c * 1.5, a);
}

fn visual_lumen_shade(uv: vec2f, sdf: f32, col: vec4f, time: f32, p: vec4f, behind: vec4f) -> vec4f {
  if (p.w > 0.5) { return vec4f(0.0); }
  let d = length(uv);
  let ang = atan2(uv.y, uv.x);
  let wob = 0.8 + 0.35 * vnoise(vec2f(ang * 2.0 + p.z * 10.0, time * 3.0));
  var c = vec3f(0.55, 0.06, 0.16) * exp(-d * d * 6.0) * wob * 1.7;
  c += vec3f(0.95, 0.15, 0.3) * exp(-pow((d - 0.55 * wob) * 5.0, 2.0)) * 0.9;
  c = max(c - vec3f(0.35) * exp(-d * d * 30.0), vec3f(0.0));
  let a = clamp(exp(-d * d * 5.0) * 1.4, 0.0, 1.0) * smoothstep(1.05, 0.8, d);
  return vec4f(c, a);
}

fn visual_lumen_bolt(uv: vec2f, sdf: f32, col: vec4f, time: f32, p: vec4f, behind: vec4f) -> vec4f {
  if (p.w > 0.5) { return vec4f(0.0); }
  let vel = vec2f(p.x, p.y);
  let sp = length(vel);
  var dir = vec2f(0.0);
  if (sp > 1.0) { dir = vel / sp; }
  let d = length(uv);
  // Hostile = ember-red. Parried = your blue.
  var hot = vec3f(1.3, 0.45, 0.12);
  if (p.z > 0.5) { hot = vec3f(0.3, 0.9, 1.25); }
  var c = hot * exp(-d * d * 16.0) * 2.5;
  for (var i = 1; i <= 3; i++) {
    let q = uv + dir * f32(i) * 0.3;
    c += hot * exp(-dot(q, q) * 24.0) * (1.0 - f32(i) * 0.25) * 0.8;
  }
  let a = clamp(exp(-d * d * 6.0) * 1.5, 0.0, 1.0);
  return vec4f(c, a);
}

fn visual_lumen_wisp(uv: vec2f, sdf: f32, col: vec4f, time: f32, p: vec4f, behind: vec4f) -> vec4f {
  let vel = vec2f(p.x, p.y);
  let sp = length(vel);
  var dir = vec2f(0.0);
  if (sp > 1.0) { dir = vel / sp; }
  var c = vec3f(0.0);
  let d = length(uv);
  c += vec3f(0.65, 0.9, 1.0) * exp(-d * d * 18.0) * 2.6;
  c += vec3f(0.2, 0.5, 1.0) * exp(-d * d * 4.0) * 0.9;
  let tl = clamp(sp / 110.0, 0.0, 1.0);
  for (var i = 1; i <= 4; i++) {
    let fi = f32(i);
    let q = uv + dir * fi * 0.28 * tl;
    c += vec3f(0.3, 0.7, 1.0) * exp(-dot(q, q) * (20.0 + fi * 10.0)) * tl * (1.0 - fi * 0.2);
  }
  c = mix(c, vec3f(1.6, 0.25, 0.2), clamp(p.z * 1.6, 0.0, 0.8));
  if (p.w > 0.5) { c *= 0.6 + 0.4 * sin(time * 20.0); }
  let a = clamp(exp(-d * d * 3.0) * 1.5, 0.0, 1.0) * smoothstep(1.05, 0.8, d);
  return vec4f(c, a);
}

fn visual_lumen_blade(uv: vec2f, sdf: f32, col: vec4f, time: f32, p: vec4f, behind: vec4f) -> vec4f {
  // Blade lies along local +y (hilt at center, tip outward). p.x = swinging.
  let d = sdSegment(uv, vec2f(0.0, 0.02), vec2f(0.0, 0.94));
  let swing = clamp(p.x, 0.0, 1.0);
  var c = vec3f(0.85, 0.97, 1.0) * exp(-d * d * 260.0) * 2.6;
  c += vec3f(0.4, 0.75, 1.0) * exp(-d * d * 38.0) * (0.65 + swing * 0.9);
  let tip = uv - vec2f(0.0, 0.94);
  c += vec3f(1.0) * exp(-dot(tip, tip) * 60.0) * 1.3;
  let a = clamp(exp(-d * d * 28.0) * 1.7, 0.0, 1.0);
  return vec4f(c, a);
}

fn visual_lumen_hud(uv: vec2f, sdf: f32, col: vec4f, time: f32, p: vec4f, behind: vec4f) -> vec4f {
  var c = vec3f(0.0);
  var a = 0.0;
  let score = p.x;
  let hp = p.y;
  for (var i = 0; i < 3; i++) {
    let q = (uv - vec2f(-0.8 + f32(i) * 0.15, 0.0)) * vec2f(6.0, 2.8);
    let on = select(0.12, 1.0, f32(i) < hp);
    let g = exp(-dot(q, q) * 1.2);
    c += vec3f(1.1, 0.2, 0.3) * g * on;
    a = max(a, g * 0.9);
  }
  for (var i = 0; i < 20; i++) {
    let row = f32(i / 10);
    let colm = f32(i % 10);
    let q = (uv - vec2f(-0.2 + colm * 0.11, (row - 0.5) * 0.5)) * vec2f(9.0, 4.0);
    let on = select(0.08, 1.0, f32(i) < score);
    let g = exp(-dot(q, q) * 1.4);
    c += vec3f(1.1, 0.8, 0.3) * g * on;
    a = max(a, g * 0.8 * on);
  }
  return vec4f(c * 1.4, clamp(a, 0.0, 1.0));
}

stepHooks.code:
try {
  const wd = sim.worldData
  if (!wd.__ch) wd.__ch = { t: 0, tier: 1, prog: 0, champs: 0, score: 0, best: 0, inv: 2, hurt: 0, flash: 0, bloom: 0, pulseE: 1, pulseT: 0, px: 0, py: 0, doubtT: 6, spaceHeld: false }
  const G = wd.__ch
  G.t += dt
  let voice = null, star = null, ring = null, hud = null
  const motes = [], doubts = []
  for (const f of sim.fields.values()) {
    const n = f.name || ''
    if (n.startsWith('Voice')) voice = f
    else if (n.startsWith('Star')) star = f
    else if (n.startsWith('Mote')) motes.push(f)
    else if (n.startsWith('Doubt')) doubts.push(f)
    else if (n.startsWith('Ring')) ring = f
    else if (n.startsWith('CHORUS')) hud = f
  }
  if (voice && star) {
    const T = f => f.transform
    const dist = (a, b) => Math.hypot(T(a).x - T(b).x, T(a).y - T(b).y)
    G.inv = Math.max(0, G.inv - dt)
    G.hurt = Math.max(0, G.hurt - dt)
    G.flash = Math.max(0, G.flash - dt * 1.6)
    G.bloom = Math.max(0, G.bloom - dt * 0.5)
    G.pulseE = Math.min(1, G.pulseE + dt / 6)
    // ── WASD flight ──
    const ACC = 360 * dt
    if (wd.key_a) T(voice).vx -= ACC
    if (wd.key_d) T(voice).vx += ACC
    if (wd.key_w) T(voice).vy -= ACC
    if (wd.key_s) T(voice).vy += ACC
    const vv = Math.hypot(T(voice).vx, T(voice).vy)
    if (vv > 165) { T(voice).vx *= 165 / vv; T(voice).vy *= 165 / vv }
    // ── Chime pulse (space) ──
    if (wd.key_space && !G.spaceHeld && G.pulseE >= 1) {
      G.pulseT = 0.55; G.pulseE = 0
      G.px = T(voice).x; G.py = T(voice).y
      for (const d of doubts) {
        if (d.visualParams && d.visualParams[3] > 0.5) continue
        const dx = T(d).x - G.px, dy = T(d).y - G.py
        const dd = Math.hypot(dx, dy) || 1
        if (dd < 130) {
          T(d).vx += dx / dd * 320; T(d).vy += dy / dd * 320
          d.properties.set('stun', 1.4)
        }
      }
    }
    G.spaceHeld = !!wd.key_space
    if (ring) {
      if (G.pulseT > 0) {
        G.pulseT = Math.max(0, G.pulseT - dt)
        T(ring).x = G.px; T(ring).y = G.py
        ring.visualParams = [1 - G.pulseT / 0.55, 1, 0, 0]
      } else {
        ring.visualParams = [0, 0, 0, 0]
      }
    }
    // ── Motes: wander free, orbit when carried ──
    let carriedCount = 0
    for (const m of motes) { if ((m.properties.get('carried') || 0) > 0) carriedCount++ }
    for (let mi = 0; mi < motes.length; mi++) {
      const m = motes[mi]
      if (m.properties.get('seed') === undefined) m.properties.set('seed', mi + 1)
      const seed = m.properties.get('seed')
      const carried = m.properties.get('carried') || 0
      if (!carried) {
        T(m).vx += Math.sin(G.t * 0.7 + seed * 2.1) * 16 * dt
        T(m).vy += Math.cos(G.t * 0.6 + seed * 3.7) * 16 * dt
        const mv = Math.hypot(T(m).vx, T(m).vy)
        if (mv > 24) { T(m).vx *= 24 / mv; T(m).vy *= 24 / mv }
        if (carriedCount < 5 && dist(m, voice) < 20) {
          m.properties.set('carried', 1)
          m.properties.set('slot', carriedCount)
          carriedCount++
        }
      } else {
        const slot = m.properties.get('slot') || 0
        const ang = G.t * 2.2 + slot * 1.2566
        const tx = T(voice).x + Math.cos(ang) * 26
        const ty = T(voice).y + Math.sin(ang) * 26
        const k = Math.min(1, dt * 10)
        T(m).x += (tx - T(m).x) * k
        T(m).y += (ty - T(m).y) * k
        T(m).vx = T(voice).vx; T(m).vy = T(voice).vy
      }
      m.visualParams = [carried, seed * 0.13, 0, 0]
    }
    // ── Deposit at the star ──
    if (dist(voice, star) < 52 && carriedCount > 0) {
      for (const m of motes) {
        if ((m.properties.get('carried') || 0) > 0) {
          m.properties.set('carried', 0)
          T(m).x = 40 + Math.random() * 432
          T(m).y = 40 + Math.random() * 432
          T(m).vx = (Math.random() - 0.5) * 20
          T(m).vy = (Math.random() - 0.5) * 20
        }
      }
      G.prog += carriedCount; G.score += carriedCount
      G.flash = 1
      carriedCount = 0
      while (G.prog >= 5) {
        G.prog -= 5; G.tier++; G.flash = 1
        for (const d of doubts) {
          const dx = T(d).x - T(star).x, dy = T(d).y - T(star).y
          const dd = Math.hypot(dx, dy) || 1
          T(d).vx += dx / dd * 260; T(d).vy += dy / dd * 260
          d.properties.set('stun', 1.0)
        }
        if (G.tier > 5) { G.champs++; G.score += 25; G.bloom = 1; G.tier = 1 }
      }
      if (G.score > G.best) G.best = G.score
    }
    // ── Doubts: spawn at edges, hunt, steal — never kill ──
    G.doubtT -= dt
    if (G.doubtT <= 0) {
      const d = doubts.find(x => x.visualParams && x.visualParams[3] > 0.5)
      if (d) {
        const side = Math.floor(Math.random() * 4)
        T(d).x = side === 0 ? 15 : side === 1 ? 497 : 50 + Math.random() * 412
        T(d).y = side === 2 ? 15 : side === 3 ? 497 : 50 + Math.random() * 412
        T(d).vx = 0; T(d).vy = 0
        d.visualParams = [0, 0, Math.random(), 0]
        d.properties.set('stun', 0)
      }
      G.doubtT = Math.max(3.0, 7.5 - G.tier * 0.7 - G.champs * 0.8)
    }
    for (const d of doubts) {
      if (!d.visualParams || d.visualParams[3] > 0.5) continue
      const stun = Math.max(0, (d.properties.get('stun') || 0) - dt)
      d.properties.set('stun', stun)
      if (stun <= 0) {
        const dx = T(voice).x - T(d).x, dy = T(voice).y - T(d).y
        const dd = Math.hypot(dx, dy) || 1
        const chase = (42 + G.tier * 6 + G.champs * 8) * dt
        T(d).vx += dx / dd * chase; T(d).vy += dy / dd * chase
        const dv = Math.hypot(T(d).vx, T(d).vy)
        const cap = 46 + G.tier * 5 + G.champs * 6
        if (dv > cap) { T(d).vx *= cap / dv; T(d).vy *= cap / dv }
      }
      // the star's aura holds doubts off
      const sx = T(d).x - T(star).x, sy = T(d).y - T(star).y
      const sd = Math.hypot(sx, sy) || 1
      if (sd < 80) { T(d).vx += sx / sd * 130 * dt; T(d).vy += sy / sd * 130 * dt }
      // contact: scatter the carried sparks
      if (dist(d, voice) < 17 && G.inv <= 0) {
        G.inv = 1.6; G.hurt = 0.6
        const kx = T(voice).x - T(d).x, ky = T(voice).y - T(d).y
        const kd = Math.hypot(kx, ky) || 1
        T(voice).vx += kx / kd * 200; T(voice).vy += ky / kd * 200
        for (const m of motes) {
          if ((m.properties.get('carried') || 0) > 0) {
            m.properties.set('carried', 0)
            const a = Math.random() * 6.283
            T(m).vx = Math.cos(a) * 60; T(m).vy = Math.sin(a) * 60
          }
        }
        carriedCount = 0
        G.score = Math.max(0, G.score - 2)
      }
      d.visualParams = [stun > 0 ? 1 : 0, 0, d.visualParams[2], 0]
    }
    // ── Feed the visuals ──
    voice.visualParams = [T(voice).vx, T(voice).vy, G.hurt, G.inv > 0 ? 1 : 0]
    star.visualParams = [G.tier, G.prog / 5, G.flash, G.bloom]
    if (hud) {
      hud.visualParams = [G.prog, carriedCount, Math.min(6, G.champs), G.pulseE]
      hud.name = 'CHORUS \u00b7 tier ' + G.tier + ' \u00b7 score ' + G.score + ' \u00b7 best ' + G.best
    }
  }
} catch (e) { /* keep the sim alive */ }

